import { PASSWORD, USERS, expect, test } from "../../fixtures";

test.describe("AUTH-03 sign in with unknown email", () => {
  test(
    "unknown email is rejected with 401 invalid_credentials",
    { tag: "@AUTH-03" },
    async ({ request }) => {
      // Arrange: a unique unknown address so parallel runs never collide with real accounts.
      const unknownEmail = `nobody-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@northwind.test`;

      // Act
      const response = await request.post("/api/auth/login", {
        data: { email: unknownEmail, password: PASSWORD },
      });

      // Assert
      expect(response.status()).toBe(401);
      const body = await response.json();
      expect(body.error.code).toBe("invalid_credentials");
    },
  );

  test(
    "unknown email is rejected the same way as a wrong password",
    { tag: "@AUTH-03" },
    async ({ request }) => {
      // Arrange
      const unknownEmail = `nobody-${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}@northwind.test`;

      // Act
      const unknownResponse = await request.post("/api/auth/login", {
        data: { email: unknownEmail, password: PASSWORD },
      });
      const wrongPasswordResponse = await request.post("/api/auth/login", {
        data: { email: USERS.member, password: "wrong-password" },
      });

      // Assert
      expect(unknownResponse.status()).toBe(wrongPasswordResponse.status());
      expect(unknownResponse.status()).toBe(401);
      const unknownBody = await unknownResponse.json();
      const wrongBody = await wrongPasswordResponse.json();
      expect(unknownBody.error.code).toBe("invalid_credentials");
      expect(unknownBody.error.code).toBe(wrongBody.error.code);
    },
  );
});
